import sys
from itertools import combinations

def max_calm_group_sum(n, a, b):
    students = list(zip(a, b))

    def can_work_together(x, y):
        return (x[0] & y[0] == x[0]) and (y[0] & x[0] == y[0])

    max_sum = 0

    for r in range(2, n + 1):
        for group in combinations(students, r):
            if all(can_work_together(group[i], group[j]) for i in range(r) for j in range(i + 1, r)):
                max_sum = max(max_sum, sum(student[1] for student in group))

    return max_sum

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:n+1]))
    b = list(map(int, data[n+1:2*n+1]))

    result = max_calm_group_sum(n, a, b)
    print(result)

if __name__ == "__main__":
    main()
